private void putAbstractTypes(final int start, final int end) {
    for (int i = start; i < end; i++) {
        Type type = currentFrame[i];
        if (type == null) {
            stackMapTableEntries.putShort(0);
        } else if (type instanceof ObjectType) {
            ObjectType objectType = (ObjectType) type;
            int typeIndex = typeIndex(objectType);
            stackMapTableEntries.putShort(typeIndex);
        } else if (type instanceof UninitializedType) {
            UninitializedType uninitializedType = (UninitializedType) type;
            int offset = uninitializedType.getOffset();
            stackMapTableEntries.putShort(0x64 | (offset >> 8));
            stackMapTableEntries.putShort(offset & 0xFF);
        } else {
            throw new IllegalArgumentException("Unexpected type: " + type);
        }
    }
}

