public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    if (u == null) {
        return null;
    }
    String path = u.getPath();
    if (path == null || path.isEmpty()) {
        return new ArrayList<>();
    }
    List<PathSegmentImpl> segments = new ArrayList<>();
    // If the path is an absolute path, ignore the leading '/'
    int start = 0;
    if (path.startsWith("/")) {
        start = 1;
    }
    if (start >= path.length()) {
        return segments;
    }
    int i = start;
    while (i < path.length()) {
        int nextSlash = path.indexOf('/', i);
        if (nextSlash == -1) {
            nextSlash = path.length();
        }
        String segment = path.substring(i, nextSlash);
        if (decode) {
            try {
                segment = URLDecoder.decode(segment, "UTF-8");
            } catch (UnsupportedEncodingException e) {
                // UTF-8 is always supported, so this should not happen
            }
        }
        segments.add(new PathSegmentImpl(segment));
        i = nextSlash + 1;
    }
    return segments;
}

