public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        return null;
    }

    // Normalize the path to use forward slashes
    String normalizedPath = path.replace('\\', '/');
    String normalizedRelativePath = relativePath.replace('\\', '/');

    // If the relative path is empty, return the original path
    if (normalizedRelativePath.isEmpty()) {
        return normalizedPath;
    }

    // If the relative path starts with a slash, it's an absolute path
    if (normalizedRelativePath.startsWith("/")) {
        return normalizedRelativePath;
    }

    // Split the path into components
    String[] pathComponents = normalizedPath.split("/");
    String[] relativeComponents = normalizedRelativePath.split("/");

    // Build the result path
    StringBuilder result = new StringBuilder();

    // Add all components from the original path
    for (String component : pathComponents) {
        if (!component.isEmpty()) {
            if (result.length() > 0) {
                result.append("/");
            }
            result.append(component);
        }
    }

    // Add all components from the relative path
    for (String component : relativeComponents) {
        if (!component.isEmpty()) {
            if (result.length() > 0) {
                result.append("/");
            }
            result.append(component);
        }
    }

    return result.toString();
}

